#include <stdio.h>

/* teste do desafio proxima-letra — counter_protocol (03-tdd 3.9.3).
   O main e o relatorio sao do harness; aqui so existem cenarios SM_TEST.
   Quem DIGITA e o teste: fopen/fprintf escrevem num arquivo os passos que
   o aluno digitaria, o freopen troca o stdin por esse arquivo, e a captura
   do stdout acontece dentro do proprio cenario (freopen + fflush, sem
   fclose no stdout). Tres cenarios com respostas diferentes: nenhuma letra
   fixa no codigo passa nos tres — a conta com a letra e obrigatoria. */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void proximaLetra(void);

SM_TEST(um_passo_e_a_letra_seguinte) {
    FILE *digitado = fopen("sm_entrada_1.tmp", "w");
    fprintf(digitado, "1\n");
    fclose(digitado);
    freopen("sm_entrada_1.tmp", "r", stdin);

    freopen("sm_saida_1.tmp", "w", stdout);
    proximaLetra();
    fflush(stdout);

    FILE *f = fopen("sm_saida_1.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("um passo depois de a", linha, "b\n",
              "a letra de partida mais 1 e a letra seguinte da fileira");
    char fim[80] = "(nada impresso)";
    fgets(fim, 80, f);
    checa_str("nao ha linha a mais", fim, "(nada impresso)",
              "a saida acaba na linha da letra: nenhuma linha extra e aceita");
    fclose(f);
}

SM_TEST(zero_passo_e_a_propria_letra) {
    FILE *digitado = fopen("sm_entrada_2.tmp", "w");
    fprintf(digitado, "0\n");
    fclose(digitado);
    freopen("sm_entrada_2.tmp", "r", stdin);

    freopen("sm_saida_2.tmp", "w", stdout);
